Let me write the code:

```cpp
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>
#include <fstream>
#include <sstream>
#include "cJSON.h"
#include "lodepng.h"

std::vector<double> getArray(cJSON* arr) {
    std::vector<double> result;
    if (cJSON_IsArray(arr)) {
        cJSON* item = NULL;
        cJSON_ArrayForEach(item, arr) {
            if (cJSON_IsArray(item)) {
                // nested array - flatten
                std::vector<double> sub = getArray(item);
                result.insert(result.end(), sub.begin(), sub.end());
            } else if (cJSON_IsNumber(item)) {
                result.push_back(item->valuedouble);
            }
        }
    }
    return result;
}

int main(int argc, char** argv) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s weights.json image.png\n", argv[0]);
        return 1;
    }

    // Load weights
    std::ifstream file(argv[1]);
    std::stringstream buffer;
    buffer << file.rdbuf();
    std::string json_str = buffer.str();
    file.close();

    cJSON* root = cJSON_Parse(json_str.c_str());
    if (!root) {
        fprintf(stderr, "Failed to parse JSON\n");
        return 1;
    }

    auto input_w = getArray(cJSON_GetObjectItem(root, "input_layer.weight"));
    auto input_b = getArray(cJSON_GetObjectItem(root, "input_layer.bias"));
    auto hidden_w = getArray(cJSON_GetObjectItem(root, "hidden_layer.weight"));
    auto hidden_b = getArray(cJSON_GetObjectItem(root, "hidden_layer.bias"));
    auto output_w = getArray(cJSON_GetObjectItem(root, "output_layer.weight"));
    auto output_b = getArray(cJSON_GetObjectItem(root, "output_layer.bias"));

    cJSON_Delete(root);

    // Load image
    std::vector<unsigned char> image;
    unsigned width, height;
    unsigned error = lodepng_decode32_file(&image, &width, &height, argv[2]);
    if (error) {
        fprintf(stderr, "PNG error: %s\n", lodepng_error_text(error));
        return 1;
    }

    // Convert to 784 floats (28x28), normalize by 255
    std::vector<double> x(784, 0.0);
    for (int i = 0; i < 784; i++) {
        x[i] = image[i * 4] / 255.0;  // R channel (grayscale = R=G=B)
    }

    // Forward pass
    // Layer 1: 784 -> 16
    std::vector<double> h1(16, 0.0);
    for (int i = 0; i < 16; i++) {
        h1[i] = input_b[i];
        for (int j = 0; j < 784; j++) {
            h1[i] += input_w[i * 784 + j] * x[j];
        }
        if (h1[i] < 0) h1[i] = 0; // ReLU
    }

    // Layer 2: 16 -> 16
    std::vector<double> h2(16, 0.0);
    for (int i = 0; i < 16; i++) {
        h2[i] = hidden_b[i];
        for (int j = 0; j < 16; j++) {
            h2[i] += hidden_w[i * 16 + j] * h1[j];
        }
        if (h2[i] < 0) h2[i] = 0; // ReLU
    }

    // Layer 3: 16 -> 10
    std::vector<double> out(10, 0.0);
    for (int i = 0; i < 10; i++) {
        out[i] = output_b[i];
        for (int j = 0; j < 16; j++) {
            out[i] += output_w[i * 16 + j] * h2[j];
        }
    }

    // Argmax
    int best = 0;
    for (int i = 1; i < 10; i++) {
        if (out[i] > out[best]) best = i;
    }

    printf("%d\n", best);

    // Also write to prediction.txt
    FILE* pf = fopen("prediction.txt", "w");
    if (pf) {
        fprintf(pf, "%d\n", best);
        fclose(pf);
    }

    return 0;
}
```

