    unsigned w = 0, h = 0;
    unsigned err = lodepng_decode32_file(&img, &w, &h, argv[2]);
    if (err) { fprintf(stderr, "PNG decode error: %s\n", lodepng_error_text(err)); return 1; }

    // RGBA -> grayscale, normalize to [0,1]
